"""Executable *test-only* OpenBot-style action boundary.

No OpenBot import, network requests, actual authorizations or tool execution.
A successful fixture decision is not authority to act on a real system.
"""
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import PurePosixPath
from urllib.parse import urlsplit
import re


def _required(value: str, field: str) -> None:
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{field} must be a nonempty string")


def _aware(value: str) -> datetime:
    _required(value, "timestamp")
    try:
        date = datetime.fromisoformat(value)
    except ValueError as exc:
        raise ValueError("Invalid ISO 8601 timestamp") from exc
    if date.tzinfo is None or date.utcoffset() is None:
        raise ValueError("Timestamp must include a timezone")
    return date


@dataclass(frozen=True)
class AuthorityLease:
    lease_id: str
    issuer: str
    actor_id: str
    worker_id: str
    mission_id: str
    tools: tuple[str, ...]
    expires_at: str
    status: str = "test_only"

    def __post_init__(self):
        for k in ("lease_id", "issuer", "actor_id", "worker_id", "mission_id"):
            _required(getattr(self, k), k)
        if type(self.status) is not str:
            raise TypeError("status must be a string")
        if self.status != "test_only":
            raise ValueError("This fixture cannot grant production authority")
        if not isinstance(self.tools, (tuple, list)) or not all(type(x) is str and x.strip() for x in self.tools):
            raise ValueError("Tool lease list is invalid")
        object.__setattr__(self, "tools", tuple(self.tools))
        _aware(self.expires_at)


@dataclass(frozen=True)
class ActionRequest:
    action_id: str
    mission_id: str
    actor_id: str
    worker_id: str
    tool: str
    target: str
    initiator: str
    requested_at: str

    def __post_init__(self):
        for k in ("action_id", "mission_id", "actor_id", "worker_id", "tool", "target", "initiator"):
            _required(getattr(self, k), k)
        _aware(self.requested_at)
        if self.tool.startswith("file."):
            path = PurePosixPath(self.target)
            if (not self.target.startswith("/workspace/") or ".." in path.parts or
                    str(path) != self.target):
                raise ValueError("File paths must be confined to an absolute /workspace/ path")
        elif self.tool.startswith("browser."):
            url = urlsplit(self.target)
            if url.scheme not in ("http", "https") or not url.hostname or url.username or url.password:
                raise ValueError("Browser requests require an HTTP(S) URL without embedded credentials")


@dataclass(frozen=True)
class ActionAudit:
    audit_id: str
    action_id: str
    mission_id: str
    actor_id: str
    worker_id: str
    tool: str
    result: str
    receipt_ref: str
    recorded_at: str
    output_digest: str
    approval_kind: str

    def __post_init__(self):
        for k in ("audit_id", "action_id", "mission_id", "actor_id", "worker_id", "tool",
                  "receipt_ref", "approval_kind"):
            _required(getattr(self, k), k)
        if self.result not in ("allowed", "refused", "failed"):
            raise ValueError("Invalid fixture action result")
        if not re.fullmatch(r"[0-9a-f]{64}", self.output_digest):
            raise ValueError("output_digest must be a SHA-256 hex digest")
        _aware(self.recorded_at)


@dataclass(frozen=True)
class ActionDecision:
    allowed_in_fixture: bool
    authorizes_real_execution: bool
    reason: str


def decide_action(request: ActionRequest, lease: AuthorityLease, now: datetime) -> ActionDecision:
    if now.tzinfo is None:
        raise ValueError("An aware evaluation time is required")
    reasons = []
    if (request.actor_id, request.worker_id, request.mission_id) != (lease.actor_id, lease.worker_id, lease.mission_id):
        reasons.append("actor, worker, or mission mismatch")
    if request.tool not in lease.tools:
        reasons.append("tool not leased")
    if _aware(lease.expires_at) <= now:
        reasons.append("lease expired")
    # No production execution path exists here even for an accepted fixture.
    return ActionDecision(not reasons, False, "; ".join(reasons) if reasons else "test fixture only")
