"""Read-only GEV proposal serialization. No HTTP client, MCP action, or GEV write."""
from datetime import datetime
from pathlib import Path
from dataclasses import asdict
from hashlib import sha256
import json
import re


def _iso(value):
    if not isinstance(value, str):
        raise ValueError("timestamp must be ISO text")
    t = datetime.fromisoformat(value)
    if t.tzinfo is None or t.utcoffset() is None:
        raise ValueError("timestamp must include timezone")
    return t


def _nonempty(value, field):
    if not isinstance(value, str) or not value.strip():
        raise ValueError(field + " required")


def _base(event_type, claim_status, evidence_class, extras):
    core = {
        "event_type": event_type,
        "status": claim_status,
        "evidence_class": evidence_class,
        "canonical_state": False,
        "read_only": True,
        "live_gev_write": False,
        "proposal_only": True,
        "GEV_runtime_tested": False,
        **extras,
    }
    digest = sha256(json.dumps(core, sort_keys=True, ensure_ascii=True, separators=(",", ":")).encode()).hexdigest()
    core["proposal_id"] = digest
    return core


def propose_audit_event(audit):
    for k in ("action_id", "mission_id", "actor_id", "worker_id", "receipt_ref"):
        _nonempty(getattr(audit, k), k)
    status = {"allowed": "EXECUTION_REPORTED_ALLOWED", "refused": "EXECUTION_DENIED", "failed": "EXECUTION_REPORTED_FAILED"}[audit.result]
    return _base("worker.action.recorded", status, "execution_receipt", {
        "audit_id": audit.audit_id,
        "action_id": audit.action_id,
        "mission_id": audit.mission_id,
        "actor_id": audit.actor_id,
        "worker_id": audit.worker_id,
        "tool": audit.tool,
        "execution_result": audit.result,
        "receipt_ref": audit.receipt_ref,
        "output_sha256": audit.output_digest,
        "source_refs": [],
        "recorded_at": audit.recorded_at,
    })


def propose_model_finding(finding, mission_id):
    _nonempty(mission_id, "mission_id")
    if finding.claim_status not in ("MODEL_OUTPUT_UNVERIFIED", "SOURCE_REVIEWED", "DISPUTED", "UNRESOLVED"):
        raise ValueError("A model finding cannot self-certify as verified")
    return _base("finding.proposed", finding.claim_status, "model_inference", {
        "mission_id": mission_id,
        "actor_id": finding.identity_id,
        "request_id": finding.request_id,
        "original_question": finding.original_question,
        "source_refs": list(finding.evidence_refs),
        "model_used": finding.model_used,
    })


def propose_source_observation(*, mission_id, source_ref, observation, retrieved_at,
                               source_time, source_verified=False, max_age_seconds=86400,
                               location=None):
    for k, v in (("mission_id", mission_id), ("source_ref", source_ref), ("observation", observation)):
        _nonempty(v, k)
    if type(source_verified) is not bool:
        raise TypeError("source_verified must be a boolean")
    if type(max_age_seconds) not in (int, float) or max_age_seconds <= 0:
        raise ValueError("max_age_seconds must be positive")
    retrieved, issued = _iso(retrieved_at), _iso(source_time)
    age = (retrieved - issued).total_seconds()
    state = "SOURCE_STALE" if age > max_age_seconds else "SOURCE_REVIEWED" if source_verified else "SOURCE_UNREVIEWED"
    pos = None
    if location is not None:
        if not isinstance(location, dict) or set(location) != {"lat", "lon"}:
            raise ValueError("location requires lat/lon")
        lat, lon = location["lat"], location["lon"]
        if type(lat) not in (int, float) or type(lon) not in (int, float) or not (-90 <= lat <= 90 and -180 <= lon <= 180):
            raise ValueError("Invalid latitude or longitude")
        pos = {"lat": lat, "lon": lon}
    return _base("source.observation.proposed", state, "source_report", {
        "mission_id": mission_id,
        "source_refs": [source_ref],
        "observation": observation,
        "retrieved_at": retrieved_at,
        "source_time": source_time,
        "location": pos,
    })


def validate_gev_proposal(p):
    if not isinstance(p, dict):
        raise ValueError("proposal must be a dictionary")
    if p.get("canonical_state") is not False or p.get("live_gev_write") is not False:
        raise ValueError("GEV proposals cannot mutate world state")
    if p.get("read_only") is not True or p.get("proposal_only") is not True:
        raise ValueError("A proposal must be explicitly read only")
    if p.get("GEV_runtime_tested") is not False:
        raise ValueError("No live GEV test evidence")
    if "intelligence_authority" in p or "response_text" in p:
        raise ValueError("Unexpected authority or unreviewed raw model output")
    if not isinstance(p.get("source_refs"), list):
        raise ValueError("source refs must be a list")
    # Explicit whitelist avoids silently exporting extra fields through the preview.
    allowed = {"event_type", "status", "evidence_class", "canonical_state", "read_only", "live_gev_write",
               "proposal_only", "GEV_runtime_tested", "proposal_id", "audit_id", "action_id", "mission_id", "actor_id",
               "worker_id", "tool", "execution_result", "receipt_ref", "output_sha256", "source_refs", "recorded_at",
               "request_id", "original_question", "model_used", "observation", "retrieved_at", "source_time", "location"}
    if set(p) - allowed:
        raise ValueError("Undeclared fields in proposal")
    source = {k:v for k,v in p.items() if k != "proposal_id"}
    expected=sha256(json.dumps(source,sort_keys=True,ensure_ascii=True,separators=(",", ":")).encode()).hexdigest()
    if not re.fullmatch(r"[0-9a-f]{64}",str(p.get("proposal_id", ""))) or p["proposal_id"] != expected:
        raise ValueError("Proposal content digest mismatch")
    return True


def export_gev_previews(proposals, path):
    proposals=list(proposals)
    ids=set()
    for p in proposals:
        validate_gev_proposal(p)
        if p["proposal_id"] in ids:
            raise ValueError("Duplicate proposal identifier")
        ids.add(p["proposal_id"])
    target=Path(path)
    target.parent.mkdir(parents=True,exist_ok=True)
    with target.open("x",encoding="utf-8") as fp:
        for p in proposals:
            fp.write(json.dumps(p,ensure_ascii=True,sort_keys=True)+"\n")
    return len(proposals)
