"""Bounded epistemic routing and persistent, reviewer-gated policy adaptation.

This is a research harness, NOT model-weight updates, calibrated confidence, an
Internet crawler, identity authentication, or a production safety system.

Purpose: visibly distinguish 'never checked' from 'checked but no evidence',
and change Dottie's next *routing* decision using independently reviewed errors.
A review is a local operator fixture plus cited receipt, not an authentication
boundary. Never promote model agreement into independently verified evidence.
"""
from dataclasses import dataclass
from hashlib import sha256
from urllib.parse import urlsplit
import ipaddress
import math
import json


EVIDENCE_STATES = frozenset({'NOT_CHECKED', 'PARTIAL', 'CONTRADICTED', 'STALE',
                             'SUPPORTED', 'NO_SOURCES'})
OUTCOMES = frozenset({'RESEARCH_REQUIRED', 'RESEARCH_NOT_REQUIRED'})
SENSITIVITY = frozenset({'public', 'internal', 'private', 'restricted'})
DEFAULT_CONFIDENCE_THRESHOLD = 0.72  # Engineering heuristic, not empirical calibration


def _bounded(value, field, max_length=2000):
    if type(value) is not str or not value.strip() or len(value) > max_length:
        raise ValueError(f'{field} requires bounded nonempty text')
    return value


def _refs(value, field, *, may_be_empty=True):
    if (not isinstance(value, (list, tuple))
            or (not may_be_empty and not value)
            or any(type(x) is not str or not x.strip() or len(x) > 500 for x in value)):
        raise ValueError(f'{field} must contain bounded source identifiers')
    return tuple(value)


@dataclass(frozen=True)
class EpistemicCase:
    case_id: str
    original_question: str
    domain: str
    evidence_state: str
    source_refs: tuple[str, ...]
    model_confidence: float
    consequence: str
    sensitivity: str
    allow_external_research: bool = False
    export_reviewed: bool = False

    def __post_init__(self):
        _bounded(self.case_id, 'case_id', 128)
        _bounded(self.original_question, 'original_question', 15000)
        _bounded(self.domain, 'domain', 100)
        if self.domain.strip() != self.domain or any(c not in 'abcdefghijklmnopqrstuvwxyz0123456789_-' for c in self.domain):
            raise ValueError('domain must be an explicit lowercase identifier')
        if self.evidence_state not in EVIDENCE_STATES:
            raise ValueError('Unknown evidence-state classification')
        refs = _refs(self.source_refs, 'source_refs')
        if self.evidence_state == 'SUPPORTED' and not refs:
            raise ValueError('SUPPORTED requires source lineage; never infer evidence')
        if type(self.model_confidence) not in (int,float) or not math.isfinite(self.model_confidence) or not 0 <= self.model_confidence <= 1:
            raise ValueError('Model confidence must be finite in [0,1]; it is not calibrated')
        if self.consequence not in ('low', 'medium', 'high'):
            raise ValueError('Consequence must be low/medium/high')
        if self.sensitivity not in SENSITIVITY:
            raise ValueError('Unknown sensitivity')
        for k in ('allow_external_research','export_reviewed'):
            if type(getattr(self,k)) is not bool:
                raise TypeError(k+' must be an actual Boolean')
        object.__setattr__(self, 'source_refs', refs)


@dataclass(frozen=True)
class EpistemicDecision:
    case_id: str
    original_question: str
    action: str
    reason: str
    required_confidence: float
    learning_basis: str
    claim_verified: bool = False
    export_permitted: bool = False


@dataclass(frozen=True)
class ResearchOutcome:
    case_id: str
    original_question: str
    status: str
    sources: tuple[dict, ...]
    claim_verified: bool = False
    model_training_performed: bool = False


class EpistemicLearning:
    """Event-sourced routing adaptation; no ML parameters, training or silent memory write."""

    def __init__(self, ledger):
        self.ledger = ledger

    def _history(self):
        # Ledger verification is fail-closed. No learning from corrupted receipts.
        self.ledger.verify()
        return self.ledger._entries()

    def _records(self):
        entries = self._history()
        cases = {}
        reviews = {}
        for e in entries:
            p = e['payload']
            if e['kind'] == 'learning.case_recorded':
                cases[p['case_id']] = p
            elif e['kind'] == 'learning.reviewed_outcome':
                reviews[p['case_id']] = p
        return cases, reviews

    def _learned_threshold(self, domain):
        cases, reviews = self._records()
        threshold = DEFAULT_CONFIDENCE_THRESHOLD
        qualified = 0
        for ident, review in reviews.items():
            original = cases.get(ident)
            if not original or original['domain'] != domain:
                continue
            qualified += 1
            was_search = original['action'] in ('SEARCH_PUBLIC', 'RESEARCH_INTERNAL', 'NEEDS_RESEARCH_PERMISSION')
            if review['outcome'] == 'RESEARCH_REQUIRED' and not was_search:
                threshold += .12  # conservative correction on a confirmed missed search
            elif review['outcome'] == 'RESEARCH_NOT_REQUIRED' and was_search:
                threshold -= .03  # bounded cost adjustment; does not defeat hard gates
        return max(.60, min(.92, round(threshold, 4))), qualified

    def decide(self, case: EpistemicCase):
        if not isinstance(case, EpistemicCase):
            raise TypeError('Explicit typed epistemic case required')
        threshold, qualified = self._learned_threshold(case.domain)
        basis = 'REVIEWED_POLICY_FEEDBACK' if qualified else 'DEFAULT_HEURISTIC_UNCALIBRATED'
        state = case.evidence_state
        if state == 'NO_SOURCES':
            action, reason = 'ABSTAIN', 'already searched but no adequate source was found; do not invent an answer'
        elif state == 'NOT_CHECKED':
            action, reason = 'RESEARCH', 'the source has not been checked; do not mistake absence of search for absence of evidence'
        elif state == 'CONTRADICTED':
            action, reason = 'RESEARCH', 'materially contradictory sources require independent reconciliation'
        elif state == 'STALE':
            action, reason = 'RESEARCH', 'source is stale for the question at hand'
        elif state == 'PARTIAL':
            action, reason = 'RESEARCH', 'available source coverage is partial'
        elif case.consequence == 'high' and len(case.source_refs) < 2:
            action, reason = 'RESEARCH', 'high-consequence response requires a second independent source check'
        elif case.model_confidence < threshold:
            action, reason = 'RESEARCH', 'uncertainty exceeds the current review-informed research threshold'
        else:
            action, reason = 'ANSWER_WITH_REFS', 'source IDs present; answer is still not independently verified by this harness'
        permitted = False
        if action == 'RESEARCH':
            if case.sensitivity != 'public':
                action, reason = 'RESEARCH_INTERNAL', 'nonpublic material must be researched through separately authorized internal tools'
            elif not case.allow_external_research or not case.export_reviewed:
                action, reason = 'NEEDS_RESEARCH_PERMISSION', 'public research is warranted but has no reviewed network/export grant'
            else:
                action = 'SEARCH_PUBLIC'
                permitted = True
        return EpistemicDecision(case_id=case.case_id,
            original_question=case.original_question, action=action, reason=reason,
            required_confidence=threshold, learning_basis=basis,
            claim_verified=False, export_permitted=permitted)

    def record_case(self, case):
        decision = self.decide(case)
        cases, _ = self._records()
        if case.case_id in cases:
            raise ValueError('Case already recorded; do not replay as a fresh event')
        self.ledger.append('learning.case_recorded', {
            'case_id':case.case_id, 'domain':case.domain,
            'original_question':case.original_question,
            'original_question_sha256':sha256(case.original_question.encode()).hexdigest(),
            'source_refs':list(case.source_refs), 'evidence_state':case.evidence_state,
            'consequence':case.consequence, 'sensitivity':case.sensitivity,
            'reported_model_confidence_UNCALIBRATED':case.model_confidence,
            'action':decision.action, 'threshold':decision.required_confidence,
            'output_verified':False, 'model_training_performed':False,
        })
        return decision

    def review_outcome(self, case_id, *, outcome, reviewer, reviewed_by_operator,
                       independent_refs, rationale):
        _bounded(case_id, 'case_id', 128)
        _bounded(reviewer, 'reviewer', 100)
        _bounded(rationale, 'rationale', 2500)
        if type(reviewed_by_operator) is not bool:
            raise TypeError('Human review requires a genuine Boolean, not text')
        # THIS IS ONLY A LOCAL TEST FIXTURE. A real user identity/authorization
        # gate is required before deployment. Model critiques never self-certify.
        if not reviewed_by_operator or reviewer != 'human-review-fixture':
            raise PermissionError('Explicit operator fixture required; a model critic cannot verify its own judgment')
        if outcome not in OUTCOMES:
            raise ValueError('Outcome is not independently adjudicated research necessity')
        refs = _refs(independent_refs, 'independent_refs', may_be_empty=False)
        if any(r.startswith(('model:', 'critic:', 'unverified:')) for r in refs):
            raise ValueError('Model output cannot serve as an independent adjudication receipt')
        cases, reviews = self._records()
        if case_id not in cases:
            raise KeyError('Cannot learn from an unrecorded case')
        if case_id in reviews:
            raise ValueError('Review is write-once; correction requires a new separately reviewed event design')
        if all(r in cases[case_id]['source_refs'] for r in refs):
            raise ValueError('Review must cite at least one source not used in original claim')
        self.ledger.append('learning.reviewed_outcome', {
            'case_id':case_id, 'reviewer_type':'HUMAN_REVIEW_FIXTURE_NOT_AUTHENTICATION',
            'outcome':outcome, 'rationale':rationale,
            'independent_refs':list(refs), 'model_output_accepted_as_authority':False,
            'weights_updated':False,
        })
        return self.decide(EpistemicCase(
            case_id=case_id + '#next-policy-probe',
            original_question=cases[case_id]['original_question'],
            domain=cases[case_id]['domain'],
            evidence_state='NOT_CHECKED',source_refs=(),model_confidence=0.0,
            consequence=cases[case_id]['consequence'],sensitivity=cases[case_id]['sensitivity'],
        )).required_confidence

    def learning_counts(self):
        cases, reviews = self._records()
        return {'observed_cases':len(cases), 'reviewed_cases':len(reviews),
                'policy_learning_active':bool(reviews),
                'model_weights_updated':False, 'independently_immutable':False,
                'persistent_replay':True}


class PublicResearchRunner:
    """Injected research provider; real network is never called by this module.

    The operator must supply a separate reviewed provider and opt-in to it.
    This layer validates returned source *references*, not their truthfulness.
    """
    def __init__(self, learning, lookup):
        if not isinstance(learning, EpistemicLearning) or not callable(lookup):
            raise TypeError('Learning gate and explicit source retrieval callable required')
        self.learning = learning
        self.lookup = lookup

    def run(self, case, *, operator_enabled):
        if type(operator_enabled) is not bool:
            raise TypeError('operator_enabled must be a Boolean')
        decision = self.learning.decide(case)
        if decision.action != 'SEARCH_PUBLIC' or not decision.export_permitted or not operator_enabled:
            raise PermissionError('External research not authorized for this case')
        # Write before any external request, so an interrupted run is not replayed.
        self.learning.record_case(case)
        try:
            sources = self.lookup(case.original_question)
            if type(sources) is not list or len(sources) > 15:
                raise ValueError('Research results must be a bounded list')
            checked = []
            for source in sources:
                if type(source) is not dict or set(source) != {'url','title','excerpt'}:
                    raise ValueError('Research source missing required provenance fields')
                url = _bounded(source['url'], 'source URL', 2048)
                u = urlsplit(url)
                if (u.scheme != 'https' or not u.hostname or u.username or u.password
                        or u.port is not None or u.fragment or u.hostname.lower() == 'localhost'):
                    raise ValueError('Untrusted or nonpublic research source URL')
                try:
                    ipaddress.ip_address(u.hostname)
                except ValueError:
                    pass
                else:
                    raise ValueError('Raw IP research sources require explicit independent review')
                checked.append({'url':url,'title':_bounded(source['title'],'title',300),
                    'excerpt':_bounded(source['excerpt'],'excerpt',6000)})
        except Exception as exc:
            # No retry: provider might have completed an external billable request.
            self.learning.ledger.append('learning.research_failed', {
                'case_id':case.case_id, 'error_type':type(exc).__name__,
                'response_is_evidence':False, 'automatic_retry':False,
            })
            raise
        state = 'RETRIEVED_UNREVIEWED' if checked else 'SEARCHED_NO_RESULTS'
        self.learning.ledger.append('learning.research_returned', {
            'case_id':case.case_id, 'status':state, 'source_urls':[r['url'] for r in checked],
            'source_verification_pending':True, 'source_text_untrusted':True,
            'model_training_performed':False,
        })
        return ResearchOutcome(case_id=case.case_id,original_question=case.original_question,
                               status=state,sources=tuple(checked))
